import com.google.common.collect.ImmutableMap;
import javax.annotation.Nonnull;

public enum Update
{
    ALL("all"),
    NONE("none");

    @Nonnull
    private final String value;

    Update(@Nonnull String value)
    {
        this.value = value;
    }

    private static final ImmutableMap<String, Update> UPDATES;

    static
    {
        ImmutableMap.Builder<String, Update> builder = new ImmutableMap.Builder<>();

        for (Update data : values())
        {
            builder.put(data.value, data);
        }

        UPDATES = builder.build();
    }

    public static Update of(String value)
    {
        if (value == null)
            return NONE;
        Update update = UPDATES.get(value.toLowerCase());
        if (update == null)
            return NONE;
        return update;
    }

    public static Update system()
    {
        return Update.of(System.getProperty("update"));
    }
}
